package com.campusiq.platform.strategy; import com.campusiq.platform.client.LeetCodeClient; import com.campusiq.platform.dto.PlatformProfileResponse; import com.campusiq.platform.entity.Platform; import org.springframework.stereotype.Component; @Component public class LeetCodeStrategy implements PlatformProfileStrategy {private final LeetCodeClient c; public LeetCodeStrategy(LeetCodeClient x){c=x;} public Platform getPlatform(){return Platform.LEETCODE;} public boolean verifyUser(String u){var p=c.profile(u);return p!=null&&p.username()!=null&&!p.username().isBlank()&&(p.errors()==null||p.errors().isBlank());} public PlatformProfileResponse fetchProfile(String u){var p=c.profile(u);var s=c.solved(u);var q=c.contest(u);return new PlatformProfileResponse(getPlatform(),p.username(),"https://leetcode.com/u/"+p.username()+"/",p.name(),p.avatar(),p.ranking(),p.reputation(),s.solvedProblem(),s.easySolved(),s.mediumSolved(),s.hardSolved(),q.contestRating(),q.contestRanking(),q.contestTopPercent(),null,null,null,null,null,null,null);}}
